-- ============================================================
--  seed_wave1_wave2_content.sql — GENERATED, paste-and-run once
--  Adds the bloom override column (idempotent) + inserts all 244
--  items authored in Wave 1 (contentPack15, difficulty-curve + variety fill)
--  and Wave 2 (contentPack16, the "depth pack" for higher-order thinking).
--  These are brand-new authored items with fresh content — safe to insert
--  directly, no risk of duplicating anything already in your cloud items table.
--  Run once in the Supabase SQL editor (Project → SQL Editor → New query).
-- ============================================================

alter table public.items add column if not exists bloom text;
comment on column public.items.bloom is
  'Optional Bloom override; null = derive from interaction_type (see lib/taxonomy.ts bloomFor).';


-- Bump content_meta so every device picks up the new items automatically.
values (1, coalesce((select version from public.content_meta where id = 1), 0) + 1, now())
on conflict (id) do update set version = excluded.version, updated_at = excluded.updated_at;
